// Fila: contatos das empresas da prospecção (Lusha, indicação ou cadastro manual de prospecção)
// que JÁ passaram pelo disparo (Follow-up ou Agendar reunião), têm LinkedIn, ainda não foram convidados
// e não estão como "não contatar".
// Ordem: quem recebeu o disparo há mais tempo primeiro. Respeita o limite por rodada e por dia.
const cfg = $('Configuração').first().json;
const FLOW = 'https://vclwmydunloeqomsmaah.supabase.co/functions/v1/api-v1';
const H = { Authorization: '***REMOVIDO***' };
const etapasAlvo = new Set($('Etapas do funil (Flow)').all().map(i => i.json).filter(e => ['Follow-up', 'Agendar reunião'].includes(e.name)).map(e => e.id));
const clientes = [...new Set($('Contratos em negociação (Flow)').all().map(i => i.json).filter(c => etapasAlvo.has(c.stage_id)).map(c => c.client_id))];
const hoje = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })).toDateString();
const fila = [];
let convidadosHoje = 0;
for (const id of clientes) {
  const r = await this.helpers.httpRequest({ method: 'GET', url: FLOW + '/leads/' + id + '/contacts', headers: H, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (r.statusCode >= 400) continue;
  const contatos = (r.body && r.body.items) || [];
  if (!contatos.some(c => c.lusha_contact_id || c.origem === 'indicacao' || c.origem === 'prospeccao_manual')) continue; // só prospecção
  for (const c of contatos) {
    if (c.linkedin_convite_em && new Date(new Date(c.linkedin_convite_em).toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })).toDateString() === hoje && c.linkedin_convite === 'enviado') convidadosHoje++;
    if (!c.linkedin || c.linkedin_convite || c.contato_status === 'nao_contatar') continue;
    if (!c.whatsapp_disparo_em && c.whatsapp_status !== 'invalido' && c.whatsapp) continue; // ainda não passou pelo disparo
    const slug = (String(c.linkedin).toLowerCase().match(/linkedin\.com\/in\/([^/?#]+)/) || [])[1];
    if (!slug) continue;
    fila.push({ lead_id: id, contato_id: c.id, nome: c.name, linkedin: c.linkedin, slug, desde: c.whatsapp_disparo_em || c.created_at });
  }
}
fila.sort((a, b) => new Date(a.desde) - new Date(b.desde));
const vagas = Math.max(0, Math.min(Number(cfg.convites_por_rodada || 5), Number(cfg.limite_por_dia || 15) - convidadosHoje));
return fila.slice(0, vagas).map(f => ({ json: { ...f, convidados_hoje_antes: convidadosHoje, fila_total: fila.length } }));

// Grava no contato do Flow: ja_conectado, enviado ou erro (para tentar de novo depois)
