  return { json: { ...f, resultado: 'perfil não encontrado (tenta de novo na próxima rodada)', erro: String((p.error && p.error.message) || p.error || '').slice(0, 200) } };
}
if (p.network_distance === 'FIRST_DEGREE') {
  campos = { linkedin_convite: 'ja_conectado', linkedin_convite_em: new Date().toISOString(), linkedin_provider_id: p.provider_id };
} else {
  const inv = $json;
  if (inv.error) return { json: { ...f, resultado: 'erro no convite (tenta de novo na próxima rodada)', erro: String(inv.error.message || inv.error).slice(0, 200) } };
  campos = { linkedin_convite: 'enviado', linkedin_convite_em: new Date().toISOString(), linkedin_provider_id: p.provider_id };
}
await this.helpers.httpRequest({ method: 'PATCH', url: FLOW + '/contacts/' + f.contato_id, headers: { Authorization: '***REMOVIDO***', 'Content-Type': 'application/json' }, body: campos, json: true });
